		&lt;tr&gt;
			&lt;td&gt;
			&lt;ol&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Conditional word + subject + v1/v5 + object, subject + will/ shall/ may + v1 + object.&lt;/span&gt;&lt;/li&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;If + subject + v2 + object, subject + would/ should/ could/ might + v1 + object.&lt;/span&gt;&lt;/li&gt;
