&lt;p&gt;अत:,&amp;nbsp;&lt;strong&gt;&lt;span class=&quot;VIiyi&quot; lang=&quot;hi&quot;&gt;&lt;span class=&quot;JLqJ4b ChMk0b&quot; data-language-for-alternatives=&quot;hi&quot; data-language-to-translate-into=&quot;en&quot; data-phrase-index=&quot;0&quot;&gt;&lt;span&gt; I और II दोनों सत्य हैं।&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

